public <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.isEmpty()) {
        return true; // An empty set trivially forms a clique.
    }

    Vertex<V,E> firstVertex = vertices.stream().findFirst().get();
    Set<Edge<V,E>> edgesToCompare = new HashSet<>();

    for (Vertex<V,E> vertex : vertices) {
        Edges.EdgeSet<V,E> vertexEdges = graph.edgesOf(vertex);
        for (Edge<V,E> edge : vertexEdges) {
            Edges.VertexSet<V,E> edgeVertices = edge.vertices();
            if (!edgeVertices.contains(vertex) && !edgeVertices.contains(firstVertex)) {
                // The edge does not connect to either of the vertices in the subgraph.
                edgesToCompare.add(edge);
            }
        }
    }

    return edgesToCompare.isEmpty(); // If edgesToCompare is empty, the subgraph is complete.
}

