private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int decoded = 0;
    // Parse out the byte sequence representing a Unicode code point
    if ((i >= 0) && (i < bb.limit())) {
        byte b1 = bb.get(i);
        switch ((b1 >> 6) & 0x3) {
            case 0:
                // One-byte sequence
                decoded = (b1 & 0x7F);
                break;
            case 1:
                // Two-byte sequence
                decoded = ((b1 & 0x1F) << 6) + bb.get(++i);
                break;
