                }
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    try {
        Enumeration<URL> resources = URLClassLoader.getSystemResources("**/" + dir);
        while (resources.hasMoreElements()) {
            URL resource = resources.nextElement();
            File file = new File(resource.getFile());
            if (file.isDirectory()) {
                addDirectoryToClassPath(cpV, file.getAbsolutePath());
            } else {
                addJarToClassPath(cpV, file.getAbsolutePath());
            }
        }
