    StringBuilder result = new StringBuilder(path);
    String[] parts = relativePath.split("/");
    for (String part : parts) {
        if (!part.isEmpty()) {
            if (part.equals(".")) {
                // Skip empty parts
            } else if (part.equals("..")) {
                // Move up one level
                if (result.length() != 0) {
                    result.delete(result.length() - 1, result.length());
                }
            } else {
                result.append("/").append(part);
            }
        }
    }
    return result.toString();
}

