private static final long FETCH_DATA_DURATION = 3600; // Example value, adjust as needed

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    if (start >= end) {
        throw new IllegalArgumentException("Start time must be less than end time");
    }
    long timeRangeSize = end - start;
    long firstRangeSize = 0;
    int rangeCount = 0;
    while (timeRangeSize > FETCH_DATA_DURATION) {
        if (firstRangeSize == 0) {
            firstRangeSize = FETCH_DATA_DURATION;
        }
        timeRanges.add(new TimeRange(start + firstRangeSize * rangeCount, start + (firstRangeSize * (rangeCount + 1))));
        timeRangeSize -= FETCH_DATA_DURATION;
        ++rangeCount;
    }
    if (timeRangeSize > 0) {
        timeRanges.add(new TimeRange(start + firstRangeSize * rangeCount, end));
    }
    return timeRanges;
}

private static class TimeRange {
    private long startTime;
    private long endTime;

